mapper.select:
SELECT SLA.DRIVER_NAME, SLA.DRIVER_PHONE, SLA.VEHICLE_PLATE, SLA.ARRIVAL_TIME, SLA.LEAVE_TIME, SLA.SUPPLIER, SLA. ID, SLA.CREATE_TIME, SLA.START_TIME, SLA.END_TIME, SP.PARK_NAME FROM SMT_LOGISTICS_APPOINTMENT SLA LEFT JOIN SMT_PARK SP ON SLA.PARK_ID = SP."ID"
AND SLA.SUPPLIER LIKE CONCAT(CONCAT('%',#{query.supplier}),'%')
AND SLA.DRIVER_NAME LIKE CONCAT(CONCAT('%',#{query.driverName}),'%')
AND SLA.VEHICLE_PLATE LIKE CONCAT(CONCAT('%',#{query.vehiclePlate}),'%')
AND SLA.PARK_ID = #{query.parkId}
AND SLA.PARK_ID IN
#{tempId}
AND SLA.STATUS = #{query.status}
AND TO_DATE(TO_CHAR(SLA.END_TIME, 'YYYY-MM-DD hh24:mi:ss'),'YYYY-MM-DD hh24:mi:ss') >= TO_Date("CONCAT"(TO_CHAR(SYSDATE,'YYYY-MM-DD'), ' 00:00:00'),'YYYY-MM-DD hh24:mi:ss') AND TO_DATE(TO_CHAR(SLA.END_TIME, 'YYYY-MM-DD hh24:mi:ss'),'YYYY-MM-DD hh24:mi:ss') < TO_Date(TO_CHAR(SYSDATE,'YYYY-MM-DD hh24:mi:ss'),'YYYY-MM-DD hh24:mi:ss')
ORDER BY SLA.CREATE_TIME DESC
